typedef struct { int node; uint64_t tokens; Queue pending; } Container;
void enqueue_io(Container* c, IOReq* r) {
  if (c->tokens >= r->cost) { c->tokens -= r->cost; submit_to_block(r); }
  else { push_back(&c->pending, r); }
}
void grant_ticket(Container* c, IOReq* r) { /* grant and submit */ }
void refill_node(int node) { /* add tokens to containers on node and wake */ }
